@import 'tailwindcss';

/* 
  Paleta "cute" de Piar: tonos pastel cálidos
  - crema de fondo, coral para acciones, menta para acentos
*/
@theme {
  --color-cream: #fff8f0;
  --color-cream-dark: #fdeee0;
  --color-coral: #ff8a80;
  --color-coral-dark: #f26a60;
  --color-mint: #a8e6cf;
  --color-mint-dark: #7dd3b0;
  --color-sky: #c7ceea;
  --color-sunflower: #ffd97d;
  --color-cocoa: #5c4f4a;
  --color-cocoa-light: #8d7f78;

  --font-sans: 'Nunito', ui-sans-serif, system-ui, sans-serif;

  --shadow-card: 0 10px 30px -8px rgb(92 79 74 / 0.25);
  --shadow-soft: 0 4px 14px -4px rgb(92 79 74 / 0.15);

  --animate-wiggle: wiggle 0.6s ease-in-out;
  --animate-pop: pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  --animate-float: float 3s ease-in-out infinite;

  @keyframes wiggle {
    0%,
    100% {
      transform: rotate(-3deg);
    }
    50% {
      transform: rotate(3deg);
    }
  }
  @keyframes pop {
    0% {
      transform: scale(0.8);
      opacity: 0;
    }
    100% {
      transform: scale(1);
      opacity: 1;
    }
  }
  @keyframes float {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-8px);
    }
  }
}

html {
  -webkit-tap-highlight-color: transparent;
}

body {
  @apply bg-cream text-cocoa font-sans antialiased;
}

import { render, screen } from '@testing-library/react'
