/** Error con mensaje amigable para la UI */
export class ApiError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'ApiError'
  }
}

import { seedBirds } from '../data/birds'
import { shelters as seedShelters } from '../data/shelters'
import { seedUsers } from '../data/users'
import type { Database } from '../types'

const DB_KEY = 'piar:db:v1'
const SESSION_KEY = 'piar:session:v1'
const SCHEMA_VERSION = 1

/** Latencia simulada de la "API" (ms). Los tests la ponen a 0. */
let latency = 250

export function setLatency(ms: number): void {
  latency = ms
}

export function delay(ms = latency): Promise<void> {
  if (ms <= 0) return Promise.resolve()
  return new Promise((resolve) => setTimeout(resolve, ms))
}

/** Identificador único sencillo y suficiente para la demo */
export function uid(prefix = 'id'): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`
}

/** Timestamp ISO actual (sobrescribible en tests) */
export function now(): string {
  return new Date().toISOString()
}

function emptyDb(): Database {
  return {
    version: SCHEMA_VERSION,
    users: [],
    shelters: [...seedShelters],
    birds: [...seedBirds],
    swipes: [],
    matches: [],
    requests: [],
    notifications: [],
    pendingReviews: [],
  }
}

/** Carga la BD desde localStorage; si no existe la siembra con los datos demo */
export function loadDb(): Database {
  try {
    const raw = localStorage.getItem(DB_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as Database
      if (parsed.version === SCHEMA_VERSION) return parsed
    }
  } catch {
    // BD corrupta: se regenera desde cero
  }
  const fresh = emptyDb()
  // los usuarios semilla se insertan aquí para poder importar fakeHash
  fresh.users = [...seedUsers]
  saveDb(fresh)
  return fresh
}

export function saveDb(db: Database): void {
  localStorage.setItem(DB_KEY, JSON.stringify(db))
}

/** Muta la BD con una función pura sobre el estado y persiste el resultado */
export function updateDb(mutator: (db: Database) => Database | void): Database {
  const db = loadDb()
  const result = mutator(db) ?? db
  saveDb(result)
  return result
}

/** Reinicia la BD a los datos de fábrica (útil en tests y en la demo) */
export function resetDb(): Database {
  localStorage.removeItem(DB_KEY)
  localStorage.removeItem(SESSION_KEY)
  return loadDb()
}

// ---- Sesión (usuario logueado) ----

export function loadSessionUserId(): string | null {
  return localStorage.getItem(SESSION_KEY)
}

export function saveSessionUserId(userId: string): void {
  localStorage.setItem(SESSION_KEY, userId)
}

export function clearSession(): void {
  localStorage.removeItem(SESSION_KEY)
}

import { fakeHash } from '../data/users'
import type { PublicUser, Role, User } from '../types'
import {
  clearSession,
  delay,
  loadDb,
  loadSessionUserId,
  now,
  saveSessionUserId,
  uid,
  updateDb,
} from './db'
import { ApiError } from './errors'

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

export interface RegisterInput {
  name: string
  email: string
  password: string
  role: Role
  /** requerido si role === 'protectora' */
  shelterId?: string
  avatar?: string
}

export function toPublicUser(user: User): PublicUser {
  const { passwordHash: _passwordHash, ...rest } = user
  return rest
}

/** Usuario logueado de forma síncrona (para hidratar la UI sin parpadeo) */
export function getCurrentUserSync(): PublicUser | null {
  const id = loadSessionUserId()
  if (!id) return null
  const user = loadDb().users.find((u) => u.id === id)
  return user ? toPublicUser(user) : null
}

export async function register(input: RegisterInput): Promise<PublicUser> {
  await delay()
  const name = input.name.trim()
  const email = input.email.trim().toLowerCase()

  if (name.length < 2) throw new ApiError('Escribe tu nombre (mínimo 2 caracteres).')
  if (!EMAIL_RE.test(email)) throw new ApiError('Ese correo no parece válido 📧')
  if (input.password.length < 6)
    throw new ApiError('La contraseña necesita al menos 6 caracteres.')

  const db = loadDb()
  if (db.users.some((u) => u.email.toLowerCase() === email))
    throw new ApiError('Ya existe una cuenta con ese correo.')

  if (input.role === 'protectora') {
    if (!input.shelterId) throw new ApiError('Elige la protectora con la que colaboras.')
    if (!db.shelters.some((s) => s.id === input.shelterId))
      throw new ApiError('Esa protectora no existe.')
  }

  const user: User = {
    id: uid('u'),
    name,
    email,
    passwordHash: fakeHash(input.password),
    role: input.role,
    avatar: input.avatar ?? (input.role === 'protectora' ? '🦜' : '🐤'),
    shelterId: input.role === 'protectora' ? input.shelterId : undefined,
  }

  updateDb((d) => {
    d.users.push(user)
    d.notifications.push({
      id: uid('n'),
      userId: user.id,
      type: 'sistema',
      title: `¡Bienvenido/a a Piar, ${user.name}! 🎉`,
      body: 'Desliza para conocer a los pajaritos que buscan hogar.',
      read: false,
      createdAt: now(),
      link: '/',
    })
  })
  saveSessionUserId(user.id)
  return toPublicUser(user)
}

export async function login(email: string, password: string): Promise<PublicUser> {
  await delay()
  const normalized = email.trim().toLowerCase()
  const user = loadDb().users.find((u) => u.email.toLowerCase() === normalized)

  if (!user || user.passwordHash !== fakeHash(password))
    throw new ApiError('El correo o la contraseña no son correctos.')

  saveSessionUserId(user.id)
  return toPublicUser(user)
}

export async function logout(): Promise<void> {
  await delay(0)
  clearSession()
}

import type { Bird, BirdSize, BirdStatus } from '../types'
import { delay, loadDb, now, uid, updateDb } from './db'
import { ApiError } from './errors'

export interface BirdFilters {
  species?: string
  location?: string
  size?: BirdSize | ''
  /** edad máxima en años */
  maxAge?: number
}

export interface BirdInput {
  name: string
  species: string
  scientificName?: string
  age: number
  sex: Bird['sex']
  size: BirdSize
  location: string
  photo: string
  story: string
  personality: string[]
  health: string
  energy: number
}

/** Pajaritos disponibles para el feed (adoptados/fuera no aparecen) */
export async function listBirds(filters: BirdFilters = {}): Promise<Bird[]> {
  await delay()
  return filterBirds(loadDb().birds.filter((b) => b.status === 'disponible'), filters)
}

/** Todas las aves de una protectora, con cualquier estado */
export async function listShelterBirds(shelterId: string): Promise<Bird[]> {
  await delay()
  return loadDb().birds.filter((b) => b.shelterId === shelterId)
}

export async function getBird(id: string): Promise<Bird> {
  await delay()
  const bird = loadDb().birds.find((b) => b.id === id)
  if (!bird) throw new ApiError('Este pajarito ya no está disponible 😔')
  return bird
}

export function filterBirds(birds: Bird[], filters: BirdFilters): Bird[] {
  return birds.filter((b) => {
    if (filters.species && b.species !== filters.species) return false
    if (filters.location && b.location !== filters.location) return false
    if (filters.size && b.size !== filters.size) return false
    if (filters.maxAge != null && b.age > filters.maxAge) return false
    return true
  })
}

/** Especies y ciudades existentes, para los desplegables de filtros */
export function getFilterOptions(birds: Bird[]): { species: string[]; locations: string[] } {
  return {
    species: [...new Set(birds.map((b) => b.species))].sort(),
    locations: [...new Set(birds.map((b) => b.location))].sort(),
  }
}

export async function createBird(shelterId: string, input: BirdInput): Promise<Bird> {
  await delay()
  validate(input)
  const db = loadDb()
  if (!db.shelters.some((s) => s.id === shelterId))
    throw new ApiError('Protectora no encontrada.')

  const bird: Bird = {
    id: uid('b'),
    shelterId,
    status: 'disponible',
    photoCredit: { artist: 'Protectora', license: 'Uso propio', page: '' },
    ...input,
    name: input.name.trim(),
    species: input.species.trim(),
    location: input.location.trim(),
    story: input.story.trim(),
    health: input.health.trim(),
  }
  updateDb((d) => {
    d.birds.push(bird)
  })
  return bird
}

export async function updateBird(id: string, patch: Partial<BirdInput>): Promise<Bird> {
  await delay()
  let updated: Bird | undefined
  updateDb((d) => {
    const bird = d.birds.find((b) => b.id === id)
    if (!bird) throw new ApiError('Pajarito no encontrado.')
    const merged = { ...bird, ...patch }
    validate(merged)
    Object.assign(bird, patch)
    updated = bird
  })
  if (!updated) throw new ApiError('Pajarito no encontrado.')
  return updated
}

export async function deleteBird(id: string): Promise<void> {
  await delay()
  updateDb((d) => {
    const bird = d.birds.find((b) => b.id === id)
    if (!bird) throw new ApiError('Pajarito no encontrado.')
    const active = d.requests.some(
      (r) => r.birdId === id && (r.status === 'pendiente' || r.status === 'aprobada'),
    )
    if (active)
      throw new ApiError('Hay solicitudes de adopción activas: resuélvelas antes de borrarlo.')
    d.birds = d.birds.filter((b) => b.id !== id)
  })
}

function validate(b: Partial<Bird>): void {
  if (!b.name?.trim()) throw new ApiError('El pajarito necesita un nombre.')
  if (!b.species?.trim()) throw new ApiError('Indica la especie.')
  if (!b.location?.trim()) throw new ApiError('Indica la ciudad donde está.')
  if (b.age == null || b.age < 0 || Number.isNaN(b.age))
    throw new ApiError('La edad no puede ser negativa.')
  if (!b.photo) throw new ApiError('Elige una foto para el pajarito.')
  if (b.energy == null || b.energy < 1 || b.energy > 5)
    throw new ApiError('La energía debe estar entre 1 y 5.')
}

/** Fecha de alta usada en listados (no persistida en Bird por simplicidad) */
export function listedAt(): string {
  return now()
}

