    await expect(birds.deleteBird(bird.id)).rejects.toThrow(/solicitudes/)
    // sin solicitudes sí se puede
    const db2 = loadDb()
    db2.requests = []
    saveDb(db2)
    await birds.deleteBird(bird.id)
    expect(loadDb().birds.some((b) => b.id === bird.id)).toBe(false)
