import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type { PublicUser } from '../types'
import { auth, loadDb, swipes } from '../services'
import type { RegisterInput } from '../services/auth'

export interface Toast {
  id: number
  message: string
  emoji: string
}

interface AppState {
  user: PublicUser | null
  /** se incrementa cuando cambian datos compartidos (matches, solicitudes…) */
  version: number
  unread: number
  toasts: Toast[]
  login: (email: string, password: string) => Promise<void>
  register: (input: RegisterInput) => Promise<void>
  logout: () => Promise<void>
  /** refresca versión + contador de no leídas */
  refresh: () => void
  toast: (message: string, emoji?: string) => void
}

const AppContext = createContext<AppState | null>(null)

const TOAST_MS = 4500

export function AppProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<PublicUser | null>(() => auth.getCurrentUserSync())
  const [version, setVersion] = useState(0)
  const [unread, setUnread] = useState(0)
  const [toasts, setToasts] = useState<Toast[]>([])
  const toastId = useRef(0)

  const refresh = useCallback(() => {
    setVersion((v) => v + 1)
    setUnread(user ? countUnread(user.id) : 0)
  }, [user])

  const toast = useCallback((message: string, emoji = '✨') => {
    const id = ++toastId.current
    setToasts((t) => [...t, { id, message, emoji }])
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), TOAST_MS)
  }, [])

  // hidrata el contador de no leídas al entrar
  useEffect(() => {
    setUnread(user ? countUnread(user.id) : 0)
  }, [user])

  // Ticker: resuelve las revisiones de las protectoras (simula tiempo de respuesta real)
  useEffect(() => {
    if (!user) return
    const tick = () => {
      const created = swipes.processPendingReviews()
      if (created.length === 0) return
      const db = loadDb()
      for (const match of created) {
        if (match.userId !== user.id) continue
        const bird = db.birds.find((b) => b.id === match.birdId)
        toast(`¡Tienes match con ${bird?.name ?? 'un pajarito'}!`, '💛')
      }
      setUnread(countUnread(user.id))
      setVersion((v) => v + 1)
    }
    tick()
    const id = setInterval(tick, 2000)
    return () => clearInterval(id)
  }, [user, toast])

  const login = useCallback(async (email: string, password: string) => {
    const u = await auth.login(email, password)
    setUser(u)
    setUnread(countUnread(u.id))
    setVersion((v) => v + 1)
  }, [])

  const register = useCallback(async (input: RegisterInput) => {
    const u = await auth.register(input)
    setUser(u)
    setUnread(countUnread(u.id))
    setVersion((v) => v + 1)
  }, [])

  const logout = useCallback(async () => {
    await auth.logout()
    setUser(null)
    setUnread(0)
  }, [])

  const value = useMemo(
    () => ({ user, version, unread, toasts, login, register, logout, refresh, toast }),
    [user, version, unread, toasts, login, register, logout, refresh, toast],
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

function countUnread(userId: string): number {
  return loadDb().notifications.filter((n) => n.userId === userId && !n.read).length
}

export function useApp(): AppState {
  const ctx = useContext(AppContext)
  if (!ctx) throw new Error('useApp debe usarse dentro de <AppProvider>')
  return ctx
}

import type { ButtonHTMLAttributes, InputHTMLAttributes, ReactNode, SelectHTMLAttributes } from 'react'

type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger'

const variants: Record<ButtonVariant, string> = {
  primary:
    'bg-coral text-white shadow-soft hover:bg-coral-dark active:scale-95 disabled:bg-cocoa-light',
  secondary: 'bg-mint text-cocoa shadow-soft hover:bg-mint-dark active:scale-95',
  ghost: 'bg-white/70 text-cocoa hover:bg-white active:scale-95 border border-cream-dark',
  danger: 'bg-white text-coral-dark border border-coral/40 hover:bg-coral/10 active:scale-95',
}

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant
}

export function Button({ variant = 'primary', className = '', ...props }: ButtonProps) {
  return (
    <button
      {...props}
      className={`rounded-full px-5 py-2.5 font-bold transition-all disabled:cursor-not-allowed disabled:opacity-60 ${variants[variant]} ${className}`}
    />
  )
}

interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  label?: string
  error?: string
}

export function Input({ label, error, id, className = '', ...props }: InputProps) {
  const inputId = id ?? props.name
  return (
    <label className="block text-sm font-semibold" htmlFor={inputId}>
      {label && <span className="mb-1.5 block text-cocoa">{label}</span>}
      <input
        id={inputId}
        {...props}
        className={`w-full rounded-2xl border-2 bg-white px-4 py-3 text-base outline-none transition-colors placeholder:text-cocoa-light/60 focus:border-coral ${
          error ? 'border-coral' : 'border-cream-dark'
        } ${className}`}
      />
      {error && <span className="mt-1 block text-xs font-semibold text-coral-dark">{error}</span>}
    </label>
  )
}

interface SelectProps extends SelectHTMLAttributes<HTMLSelectElement> {
  label?: string
}

export function Select({ label, className = '', children, ...props }: SelectProps) {
  const id = props.name
  return (
    <label className="block text-sm font-semibold" htmlFor={id}>
      {label && <span className="mb-1.5 block text-cocoa">{label}</span>}
      <select
        id={id}
        {...props}
        className={`w-full cursor-pointer appearance-none rounded-2xl border-2 border-cream-dark bg-white px-4 py-3 text-base outline-none transition-colors focus:border-coral ${className}`}
      >
        {children}
      </select>
    </label>
  )
}

export function Tag({ children }: { children: ReactNode }) {
  return (
    <span className="rounded-full bg-cream-dark px-3 py-1 text-xs font-bold text-cocoa-light">
      {children}
    </span>
  )
}

export function Spinner({ label = 'Cargando…' }: { label?: string }) {
  return (
    <div className="flex flex-col items-center gap-3 py-10 text-cocoa-light" role="status">
      <span className="text-4xl animate-wiggle">🐦</span>
      <span className="text-sm font-semibold">{label}</span>
    </div>
  )
}

export function EmptyState({
  emoji,
  title,
  children,
}: {
  emoji: string
  title: string
  children?: ReactNode
}) {
  return (
    <div className="mx-auto max-w-sm rounded-3xl bg-white p-8 text-center shadow-soft">
      <div className="mb-3 text-5xl animate-float">{emoji}</div>
      <h2 className="mb-2 text-lg font-extrabold text-cocoa">{title}</h2>
      <p className="text-sm text-cocoa-light">{children}</p>
    </div>
  )
}

/** Botón redondo grande para las acciones del swipe */
export function CircleButton({
  emoji,
  label,
  onClick,
  size = 'md',
  tone = 'plain',
}: {
  emoji: string
  label: string
  onClick?: () => void
  size?: 'sm' | 'md'
  tone?: 'plain' | 'like' | 'nope' | 'super'
}) {
  const tones = {
    plain: 'bg-white text-cocoa border-cream-dark hover:border-cocoa-light',
    like: 'bg-mint text-cocoa border-mint-dark hover:bg-mint-dark',
    nope: 'bg-white text-coral-dark border-coral/40 hover:bg-coral/10',
    super: 'bg-sky text-cocoa border-[#8f9fd6] hover:brightness-95',
  }
  const sizes = { sm: 'h-12 w-12 text-xl', md: 'h-14 w-14 text-2xl' }
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      className={`grid place-items-center rounded-full border-2 shadow-soft transition-all active:scale-90 ${tones[tone]} ${sizes[size]}`}
    >
      {emoji}
    </button>
  )
}

import { useEffect, useRef, useState } from 'react'
import { NavLink, Outlet, useNavigate } from 'react-router-dom'
import type { AppNotification } from '../types'
import { notifications as notificationsApi } from '../services'
import { useApp } from '../store/AppContext'
import { Button } from './ui'

const TYPE_ICON: Record<AppNotification['type'], string> = {
  match: '💛',
  solicitud: '📝',
  estado: '📣',
  sistema: '🎉',
}

export default function Layout() {
  const { user, unread, toasts, refresh, logout } = useApp()
  const navigate = useNavigate()

  const links =
    user?.role === 'protectora'
      ? [
          { to: '/dashboard', emoji: '📋', label: 'Panel' },
          { to: '/', emoji: '🐦', label: 'Mi pajarito' },
        ]
      : [
          { to: '/', emoji: '🐦', label: 'Descubrir' },
          { to: '/matches', emoji: '💛', label: 'Matches' },
          { to: '/adopciones', emoji: '🏡', label: 'Adopciones' },
        ]

  return (
    <div className="flex min-h-dvh flex-col">
      <header className="sticky top-0 z-40 border-b border-cream-dark bg-cream/90 backdrop-blur">
        <div className="mx-auto flex max-w-5xl items-center gap-3 px-4 py-3">
          <NavLink to="/" className="flex items-center gap-2" aria-label="Piar, inicio">
            <img src="/favicon.svg" alt="" className="h-9 w-9" />
            <span className="hidden text-xl font-extrabold text-coral-dark sm:block">Piar</span>
          </NavLink>

          <nav className="ml-2 flex flex-1 items-center gap-1 overflow-x-auto">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.to === '/'}
                className={({ isActive }) =>
                  `flex shrink-0 items-center gap-1.5 rounded-full px-3 py-2 text-sm font-bold transition-colors ${
                    isActive ? 'bg-coral text-white shadow-soft' : 'text-cocoa hover:bg-white'
                  }`
                }
              >
                <span aria-hidden>{l.emoji}</span>
                <span className="hidden sm:inline">{l.label}</span>
              </NavLink>
            ))}
          </nav>

          <Bell />

          <button
            type="button"
            onClick={() => navigate('/perfil')}
            className="flex items-center gap-2 rounded-full bg-white py-1.5 pl-1.5 pr-3 shadow-soft transition-transform active:scale-95"
            title="Mi perfil"
          >
            <span className="grid h-8 w-8 place-items-center rounded-full bg-cream-dark text-lg">
              {user?.avatar}
            </span>
            <span className="hidden text-sm font-bold sm:block">{user?.name}</span>
          </button>

          <Button
            variant="ghost"
            className="!px-3 !py-2 text-sm"
            onClick={async () => {
              await logout()
              navigate('/login')
              refresh()
            }}
          >
            Salir
          </Button>
        </div>
      </header>

      <main className="mx-auto w-full max-w-5xl flex-1 px-4 py-6">
        <Outlet />
      </main>

      {/* Aviso flotante de toasts */}
      <div
        className="pointer-events-none fixed inset-x-0 bottom-20 z-50 flex flex-col items-center gap-2 px-4 sm:bottom-6"
        aria-live="polite"
      >
        {toasts.map((t) => (
          <div
            key={t.id}
            className="animate-pop rounded-full bg-cocoa px-5 py-3 text-sm font-bold text-white shadow-card"
          >
            <span className="mr-2">{t.emoji}</span>
            {t.message}
          </div>
        ))}
      </div>
    </div>
  )
}

/** Campana de notificaciones con panel desplegable */
function Bell() {
  const { unread, version, refresh } = useApp()
  const [open, setOpen] = useState(false)
  const [items, setItems] = useState<AppNotification[]>([])
  const navigate = useNavigate()
  const panelRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    let active = true
    notificationsApi.listNotifications(useCurrentUser()).then((list) => {
      if (active) setItems(list)
    })
    return () => {
      active = false
    }
  }, [open, version])

  async function openPanel() {
    setOpen((o) => !o)
  }

  async function toggleAllRead() {
    await notificationsApi.markAllNotificationsRead(useCurrentUser())
    refresh()
    setOpen(false)
  }

  async function onItemClick(n: AppNotification) {
    await notificationsApi.markNotificationRead(n.id)
    refresh()
    setOpen(false)
    if (n.link) navigate(n.link)
  }

  return (
    <div className="relative" ref={panelRef}>
      <button
        type="button"
        onClick={openPanel}
        aria-label={`Notificaciones${unread ? `, ${unread} sin leer` : ''}`}
        className="relative grid h-10 w-10 place-items-center rounded-full bg-white shadow-soft transition-transform active:scale-90"
      >
        🔔
        {unread > 0 && (
          <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-coral px-1 text-[10px] font-extrabold text-white">
            {unread > 9 ? '9+' : unread}
          </span>
        )}
      </button>

      {open && (
        <>
          <button
            type="button"
            aria-label="Cerrar notificaciones"
            className="fixed inset-0 z-40 cursor-default"
            onClick={() => setOpen(false)}
          />
          <div className="absolute right-0 z-50 mt-2 w-80 max-w-[calc(100vw-2rem)] overflow-hidden rounded-3xl bg-white shadow-card">
            <div className="flex items-center justify-between border-b border-cream-dark px-4 py-3">
              <span className="font-extrabold">Notificaciones</span>
              {items.some((n) => !n.read) && (
                <button
                  type="button"
                  onClick={toggleAllRead}
                  className="text-xs font-bold text-coral-dark hover:underline"
                >
                  Marcar todo leído
                </button>
              )}
            </div>
            <ul className="max-h-80 overflow-y-auto">
              {items.length === 0 && (
                <li className="px-4 py-6 text-center text-sm text-cocoa-light">
                  Aún no tienes notificaciones 🕊️
                </li>
              )}
              {items.map((n) => (
                <li key={n.id}>
                  <button
                    type="button"
                    onClick={() => onItemClick(n)}
                    className={`flex w-full gap-3 px-4 py-3 text-left transition-colors hover:bg-cream ${
                      n.read ? 'opacity-60' : ''
                    }`}
                  >
                    <span className="text-xl">{TYPE_ICON[n.type]}</span>
                    <span className="min-w-0">
                      <span className="block text-sm font-bold">{n.title}</span>
                      <span className="block text-xs text-cocoa-light">{n.body}</span>
                      <span className="mt-0.5 block text-[10px] text-cocoa-light/70">
                        {timeAgo(n.createdAt)}
                      </span>
                    </span>
                    {!n.read && <span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-coral" />}
                  </button>
                </li>
              ))}
            </ul>
          </div>
        </>
      )}
    </div>
  )
}

/** id del usuario logueado (evita imports circulares con el contexto en el panel) */
function useCurrentUser(): string {
  // pequeño hook local reutilizando el contexto
  const { user } = useApp()
  if (!user) throw new Error('Sesión no iniciada')
  return user.id
}

function timeAgo(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime()
  const min = Math.floor(diff / 60000)
  if (min < 1) return 'ahora mismo'
  if (min < 60) return `hace ${min} min`
  const h = Math.floor(min / 60)
  if (h < 24) return `hace ${h} h`
  return `hace ${Math.floor(h / 24)} d`
}

