import { useEffect, useState, type FormEvent } from 'react'
import { Link } from 'react-router-dom'
import { shelters } from '../data/shelters'
import { handlePhotoError } from '../lib/photo'
import type { MatchWithBird } from '../services/matches'
import type { RequestWithContext } from '../services/requests'
import { ApiError, matches as matchesApi, requests as requestsApi } from '../services'
import { Button, EmptyState, RequestBadge, Spinner } from '../components/ui'
import { useApp } from '../store/context'

export default function Matches() {
  const { user, version, refresh, toast } = useApp()
  const [list, setList] = useState<MatchWithBird[] | null>(null)
  const [reqs, setReqs] = useState<RequestWithContext[]>([])
  const [openForm, setOpenForm] = useState<string | null>(null)
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)

  useEffect(() => {
    if (!user) return
    matchesApi.listMatchesForUser(user.id).then(setList)
    requestsApi.listRequestsForUser(user.id).then(setReqs)
  }, [user, version])

  async function submit(e: FormEvent, matchId: string) {
    e.preventDefault()
    if (!user) return
    setBusy(true)
    try {
      await requestsApi.createRequest(user.id, matchId, message)
      toast('Solicitud enviada a la protectora 📝')
      setMessage('')
      setOpenForm(null)
      refresh()
    } catch (err) {
      toast(err instanceof ApiError ? err.message : 'No se pudo enviar', '⚠️')
    } finally {
      setBusy(false)
    }
  }

  if (!list) return <Spinner label="Buscando tus matches…" />

  if (list.length === 0) {
    return (
      <div className="mx-auto max-w-md">
        <EmptyState emoji="💛" title="Aún no hay matches">
          Sigue deslizando: cuando la protectora corresponda a tu like, aparecerá aquí.
        </EmptyState>
        <div className="mt-6 text-center">
          <Link to="/">
            <Button>Descubrir pajaritos</Button>
          </Link>
        </div>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-lg">
      <h1 className="mb-4 text-2xl font-extrabold">Tus matches 💛</h1>
      <ul className="space-y-4">
        {list.map((m) => {
          const shelter = shelters.find((s) => s.id === m.shelterId)
          const req = reqs.find((r) => r.matchId === m.id)
          const isOpen = openForm === m.id
          return (
            <li key={m.id} className="overflow-hidden rounded-3xl bg-white shadow-soft">
              <div className="flex gap-4 p-4">
                <Link to={`/pajarito/${m.bird.id}`} className="shrink-0">
                  <img
                    src={m.bird.photo}
                    alt={m.bird.name}
                    onError={handlePhotoError}
                    className="h-24 w-24 rounded-2xl object-cover"
                  />
                </Link>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <h2 className="text-xl font-extrabold">{m.bird.name}</h2>
                    {req && <RequestBadge status={req.status} />}
                  </div>
                  <p className="text-sm text-cocoa-light">
                    {m.bird.species} · {m.bird.location}
                  </p>
                  <p className="mt-0.5 text-xs font-semibold text-mint-dark">
                    🦜 {shelter?.name ?? 'Protectora'}
                  </p>

                  {req ? (
                    <p className="mt-2 text-sm text-cocoa-light">
                      Solicitud enviada · {new Date(req.createdAt).toLocaleDateString('es-ES')}
                    </p>
                  ) : (
                    <Button
                      className="mt-2 !px-4 !py-1.5 text-sm"
                      onClick={() => setOpenForm(isOpen ? null : m.id)}
                    >
                      {isOpen ? 'Cancelar' : 'Solicitar adopción 💌'}
                    </Button>
                  )}
                </div>
              </div>

              {isOpen && (
                <form onSubmit={(e) => submit(e, m.id)} className="border-t border-cream-dark p-4">
                  <label className="mb-1.5 block text-sm font-bold" htmlFor={`msg-${m.id}`}>
                    Cuéntale a {shelter?.name} por qué queréis adoptar a {m.bird.name}
                  </label>
                  <textarea
                    id={`msg-${m.id}`}
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    rows={3}
                    required
                    minLength={10}
                    placeholder="Tenemos una jaula grande, un balcón soleado y mucho cariño…"
                    className="w-full rounded-2xl border-2 border-cream-dark bg-white px-4 py-3 text-sm outline-none focus:border-coral"
                  />
                  <div className="mt-3 flex justify-end gap-2">
                    <Button
                      type="button"
                      variant="ghost"
                      className="!px-4 !py-2 text-sm"
                      onClick={() => setOpenForm(null)}
                    >
                      Volver
                    </Button>
                    <Button type="submit" disabled={busy} className="!px-4 !py-2 text-sm">
                      {busy ? 'Enviando…' : 'Enviar solicitud'}
                    </Button>
                  </div>
                </form>
              )}
            </li>
          )
        })}
      </ul>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { handlePhotoError } from '../lib/photo'
import type { RequestWithContext } from '../services/requests'
import { requests as requestsApi } from '../services'
import { Button, EmptyState, RequestBadge, Spinner } from '../components/ui'
import { useApp } from '../store/context'

const STATUS_HELP: Record<string, string> = {
  pendiente: 'La protectora revisará tu solicitud en breve.',
  aprobada: '¡Genial! Coordina la entrega con la protectora.',
  rechazada: 'No te preocupes: hay más pajaritos esperando hogar.',
  completada: '¡Felicidades! La adopción está completa.',
}

export default function Adoptions() {
  const { user, version } = useApp()
  const [list, setList] = useState<RequestWithContext[] | null>(null)

  useEffect(() => {
    if (!user) return
    requestsApi.listRequestsForUser(user.id).then(setList)
  }, [user, version])

  if (!list) return <Spinner label="Cargando tus adopciones…" />

  if (list.length === 0) {
    return (
      <div className="mx-auto max-w-md">
        <EmptyState emoji="🏡" title="Todavía no has solicitado ninguna adopción">
          Cuando tengas un match, pulsa «Solicitar adopción» y podrás seguir su estado aquí.
        </EmptyState>
        <div className="mt-6 text-center">
          <Link to="/">
            <Button>Ver pajaritos</Button>
          </Link>
        </div>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-lg">
      <h1 className="mb-4 text-2xl font-extrabold">Mis adopciones 🏡</h1>
      <ul className="space-y-4">
        {list.map((r) => (
          <li key={r.id} className="flex gap-4 rounded-3xl bg-white p-4 shadow-soft">
            <Link to={`/pajarito/${r.birdId}`} className="shrink-0">
              <img
                src={r.birdPhoto}
                alt={r.birdName}
                onError={handlePhotoError}
                className="h-20 w-20 rounded-2xl object-cover"
              />
            </Link>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <h2 className="text-lg font-extrabold">{r.birdName}</h2>
                <RequestBadge status={r.status} />
              </div>
              <p className="text-sm text-cocoa-light">🦜 {r.shelterName}</p>
              <p className="mt-1 text-sm text-cocoa">{STATUS_HELP[r.status]}</p>
              <p className="mt-2 text-xs text-cocoa-light/70">
                Enviada el {new Date(r.createdAt).toLocaleDateString('es-ES')}
                {r.updatedAt !== r.createdAt &&
                  ` · actualizada el ${new Date(r.updatedAt).toLocaleDateString('es-ES')}`}
              </p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  )
}

import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it } from 'vitest'
import App from '../App'
import * as auth from '../services/auth'
import { swipes, requests } from '../services'
import { setLatency } from '../services/db'

/** Crea un match real de la usuario demo sobre Tornasol (b1) */
async function seedMatch() {
  await swipes.sendSwipe('u1', 'b1', 'superlike')
  return swipes.processPendingReviews(Date.now() + 60_000)[0]
}

beforeEach(async () => {
  localStorage.clear()
  setLatency(0)
  await auth.login('ana@piar.app', 'demo1234')
})

describe('matches', () => {
  it('muestra el estado vacío cuando no hay matches', async () => {
    window.history.pushState({}, '', '/matches')
    render(<App />)
    expect(await screen.findByText(/aún no hay matches/i)).toBeInTheDocument()
  })

  it('lista el match con su pajarito y protectora', async () => {
    const match = await seedMatch()
    expect(match).toBeTruthy()

    window.history.pushState({}, '', '/matches')
    render(<App />)

    expect(await screen.findByRole('heading', { name: 'Tornasol' })).toBeInTheDocument()
    expect(screen.getByText(/Ala de Barrio/)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /solicitar adopción/i })).toBeInTheDocument()
  })

  it('permite enviar la solicitud con un mensaje válido', async () => {
    await seedMatch()
    const user = userEvent.setup()
    window.history.pushState({}, '', '/matches')
    render(<App />)

    await user.click(await screen.findByRole('button', { name: /solicitar adopción/i }))
    await user.type(
      screen.getByLabelText(/cuéntale a ala de barrio/i),
      'Tenemos una jaula grande y un balcón soleado.',
    )
    await user.click(screen.getByRole('button', { name: /enviar solicitud/i }))

    expect(await screen.findByText(/solicitud enviada a la protectora/i)).toBeInTheDocument()
    expect(await screen.findByText('Pendiente ⏳')).toBeInTheDocument()
    // el formulario se cierra
    expect(screen.queryByRole('button', { name: /enviar solicitud/i })).not.toBeInTheDocument()
  })

  it('rechaza un mensaje demasiado corto con un aviso', async () => {
    await seedMatch()
    const user = userEvent.setup()
    window.history.pushState({}, '', '/matches')
    render(<App />)

    await user.click(await screen.findByRole('button', { name: /solicitar adopción/i }))
    await user.type(screen.getByLabelText(/cuéntale a ala de barrio/i), 'hola')
    await user.click(screen.getByRole('button', { name: /enviar solicitud/i }))

    expect(await screen.findByText(/10 caracteres/i)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /solicitar adopción/i })).toBeInTheDocument()
  })
})

describe('adopciones', () => {
  it('muestra el estado vacío si no hay solicitudes', async () => {
    window.history.pushState({}, '', '/adopciones')
    render(<App />)
    expect(await screen.findByText(/no has solicitado ninguna adopción/i)).toBeInTheDocument()
  })

  it('sigue el estado: pendiente → aprobada por la protectora', async () => {
    const match = await seedMatch()
    await requests.createRequest('u1', match.id, 'Quiero que viva con nosotros')

    window.history.pushState({}, '', '/adopciones')
    const first = render(<App />)
    expect(await screen.findByText('Pendiente ⏳')).toBeInTheDocument()
    expect(screen.getByText(/revisará tu solicitud/i)).toBeInTheDocument()
    first.unmount()

    // la protectora aprueba (simulación directa del servicio)
    const req = (await requests.listRequestsForUser('u1'))[0]
    await requests.updateRequestStatus(req.id, 'u2', 'aprobada')

    render(<App />)
    expect(await screen.findByText('Aprobada 💚')).toBeInTheDocument()
    expect(screen.getByText(/coordina la entrega/i)).toBeInTheDocument()
    await waitFor(() => expect(screen.getByText(/enviada el/i)).toBeInTheDocument())
  })
})

