import { DatabaseSync } from 'node:sqlite'
import { writeFileSync } from 'node:fs'

const SESSION = 'ses_eeefc1ca1ffeA6QiI7I7CNlJ5i'
const OUT = '/var/www/MasterIA/pruebaOpenCode/docs/transcripcion-conversacion.md'
const db = new DatabaseSync(process.env.HOME + '/.local/share/opencode/opencode.db', { readOnly: true })

const rows = db.prepare(
  'SELECT type, data, seq FROM session_message WHERE session_id = ? ORDER BY seq'
).all(SESSION)
db.close()

const hhmm = (ms) => new Date(ms).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
const short = (s, n = 110) => {
  const t = String(s).replace(/\s+/g, ' ').trim()
  return t.length > n ? t.slice(0, n - 1) + '…' : t
}
const firstText = (state) => {
  const c = state?.content
  if (Array.isArray(c)) {
    const t = c.find((x) => x.type === 'text')
    if (t?.text) return t.text
  }
  return ''
}

function toolSummary(name, input) {
  const i = input || {}
  switch (name) {
    case 'shell': return short(i.command, 140)
    case 'read': return i.path + (i.offset ? ` (offset ${i.offset})` : '')
    case 'write': return i.path
    case 'edit': return i.path
    case 'glob': return short(i.pattern, 60)
    case 'grep': return `${short(i.pattern, 60)}${i.path ? ' en ' + i.path : ''}`
    case 'webfetch': return short(i.url, 90)
    case 'websearch': return short(i.query, 90)
    case 'skill': return i.id
    case 'subagent': return `${i.agent}: ${i.description}`
    case 'question': return short(i.questions?.[0]?.question, 90)
    default: return short(JSON.stringify(i), 90)
  }
}

let out = `# Transcripción de la conversación con OpenCode

- **Proyecto:** Piar — \`/var/www/MasterIA/pruebaOpenCode\`
- **Sesión:** \`${SESSION}\` — «Saludo inicial en español»
- **Mensajes:** ${rows.length}
- **Exportado:** ${new Date().toLocaleString('es-ES')}

> Incluye los mensajes del usuario y las respuestas del asistente textualmente.
> Las llamadas a herramientas aparecen abreviadas (🔧) y se omiten los razonamientos
> internos, las salidas completas de comandos y los recordatorios del sistema (estos
> últimos, solo como nota breve). Véase también \`.git\` de la sesión original si hace
> falta el detalle bruto.

---
`

let lastUser = null
for (const r of rows) {
  const d = JSON.parse(r.data)
  const t = hhmm(d.time?.created || 0)

  if (r.type === 'user') {
    if (d.text) {
      out += `\n## 👤 Usuario  <sub>${t}</sub>\n\n${d.text.trim()}\n`
      lastUser = d.text.trim().slice(0, 60)
    }
  } else if (r.type === 'assistant') {
    for (const c of d.content || []) {
      if (c.type === 'text' && c.text.trim()) {
        out += `\n## 🤖 Asistente  <sub>${t}</sub>\n\n${c.text.trim()}\n`
      } else if (c.type === 'tool') {
        const status = c.state?.status
        const flag = status && status !== 'completed' ? ` *(⚠️ ${status})*` : ''
        const res = c.name === 'shell' && firstText(c.state) ? ` — ${short(firstText(c.state), 100)}` : ''
        out += `\n- 🔧 \`${c.name}\` ${toolSummary(c.name, c.state?.input)}${flag}${res}\n`
      }
    }
  } else if (r.type === 'compaction') {
    out += `\n> ⚙️ *${t} — Resumen automático de contexto (compactación): el historial se resumió aquí; el detalle completo de las fases anteriores no se incluye en esta exportación.*\n`
  } else if (r.type === 'synthetic') {
    const first = short(d.text, 220)
    out += `\n> ⚙️ *${t} — Recordatorio del sistema: ${first}*\n`
  } else if (r.type === 'system') {
    out += `\n> ⚙️ *${t} — Instrucciones cargadas (${d.metadata?.notice || 'system'}): ${short(d.text, 120)}*\n`
  } else if (r.type === 'agent-switched') {
    out += `\n> ⚙️ *${t} — Cambio de agente: ${d.previous} → ${d.agent}*\n`
  }
}

writeFileSync(OUT, out)
console.log('OK →', OUT)
console.log('líneas:', out.split('\n').length, '| tamaño:', (out.length / 1024).toFixed(1) + ' KB')

