function extractOut(st) {
  if (!st) return ''
  const c = st.content
  if (typeof c === 'string') return c
  if (Array.isArray(c)) return c.map((b) => (b && typeof b.text === 'string' ? b.text : '')).filter(Boolean).join(' ')
  if (typeof st.output === 'string') return st.output
