import { DatabaseSync } from 'node:sqlite'
import fs from 'node:fs'

const DB = 'C:\\Users\\mbmartinez\\.local\\share\\opencode\\opencode.db'
const SID = 'ses_eeefc1ca1ffeA6QiI7I7CNlJ5i'
const OUT = '\\\\wsl.localhost\\Ubuntu-26.04-RECOVERY\\var\\www\\MasterIA\\pruebaOpenCode\\sesion.json'

const db = new DatabaseSync(DB, { readOnly: true })
const row = db.prepare('SELECT * FROM session_v2 WHERE id = ?').get(SID)
console.log('cols session_v2:', Object.keys(row).join(','))
const pick = (...names) => { for (const n of names) if (row[n] !== undefined) return row[n]; return undefined }
const info = {
  id: row.id,
  projectID: pick('project_id', 'projectID'),
  agent: row.agent,
  model: typeof row.model === 'string' ? JSON.parse(row.model) : row.model,
  cost: row.cost,
  tokens: {
    input: pick('tokens_input', 'tokensInput'),
    output: pick('tokens_output', 'tokensOutput'),
    reasoning: pick('tokens_reasoning', 'tokensReasoning'),
    cache: {
      read: pick('tokens_cache_read', 'tokensCacheRead'),
      write: pick('tokens_cache_write', 'tokensCacheWrite'),
    },
  },
  outcome: pick('idle_outcome', 'outcome'),
  time: {
    created: row.time_created,
    updated: row.time_updated,
    idle: pick('time_idle', 'timeIdle'),
    viewed: pick('time_viewed', 'timeViewed'),
  },
  title: row.title,
  location: { directory: row.directory },
}
const rows = db.prepare('SELECT id, type, data FROM session_message WHERE session_id = ? ORDER BY seq').all(SID)
const messages = rows.map((r) => {
  const d = JSON.parse(r.data)
  return { id: r.id, ...d, type: r.type }
})
db.close()

// compara la estructura de info con la del fichero anterior (si existe)
try {
  const old = JSON.parse(fs.readFileSync(OUT, 'utf8'))
  const flatKeys = (o, p = '') => Object.entries(o).flatMap(([k, v]) => (v && typeof v === 'object' && !Array.isArray(v) ? flatKeys(v, p + k + '.') : [p + k]))
  const a = flatKeys(old.info).sort().join('|')
  const b = flatKeys(info).filter((k) => info[k.split('.')[0]] !== undefined).sort().join('|')
  console.log('info keys anterior == nueva:', a === b ? 'SÍ' : 'NO')
  if (a !== b) { console.log('anterior:', a); console.log('nueva   :', b) }
  console.log('mensajes anterior:', old.messages.length, '→ nuevo:', messages.length)
} catch (e) {
  console.log('sin sesion.json anterior:', e.message)
}

fs.writeFileSync(OUT, JSON.stringify({ info, messages }, null, 2) + '\n', 'utf8')
console.log('OK escrito —', messages.length, 'mensajes')
